 56	export async function runTool<A, E>(
 57	  runtime: SubagentRuntime,
 58	  effect: Effect.Effect<A, E>,
 59	  options: { signal?: AbortSignal; interruptMessage?: string } = {},
 60	) {
 61	  const exit = await runtime.runPromiseExit(
 62	    effect,
 63	    options.signal ? { signal: options.signal } : undefined,
 64	  );
 65	  if (Exit.isSuccess(exit)) return exit.value;
 66	  const [first] = Cause.prettyErrors(exit.cause);
 67	  if (Cause.hasInterrupts(exit.cause)) {
 68	    const interrupted = options.interruptMessage ?? "Operation was aborted.";
 69	    const detail = Cause.hasInterruptsOnly(exit.cause)
 70	      ? ""
 71	      : ` ${first?.message ?? Cause.pretty(exit.cause)}`;
 72	    throw new SubagentToolInterruptedError(`${interrupted}${detail}`);
 73	  }
 74	  throw new Error(first?.message ?? Cause.pretty(exit.cause));
 75	}

