     7	export interface SubagentResultDeliveryOptions<T> {
     8	  /** True only when the parent has no run or queued continuation in flight. */
     9	  readonly isIdle: () => boolean;
    10	  /** Deliver one drained batch and wake the parent. */
    11	  readonly deliver: (results: readonly T[]) => void;
    12	  /** Current Pi Session transcript owner. */
    13	  readonly owner?: () => CompletionOwner | undefined;
    14	}
    15	
    16	/**
    17	 * One-shot result delivery for fire-and-forget subagents.
    18	 *
    19	 * The tool contract promises that a settled child re-invokes the parent. A
    20	 * child that settles while the parent is busy therefore remains retractable
    21	 * until the parent's `agent_settled` event, but it must never be downgraded to
    22	 * a `nextTurn` message that needs another user prompt. There are two symmetric
    23	 * wake-up edges so no ordering can lose the notification:
    24	 *
    25	 * 1. child settles after the parent became idle -> `defer` flushes now;
    26	 * 2. parent settles after the child -> `parentSettled` flushes the batch.
    27	 *
    28	 * The parent boundary wakes even if an earlier extension handler has already
    29	 * started another turn: Pi queues the follow-up into that active run.
    30	 *
    31	 * The shared inbox is the one-shot gate: `subagent_wait` may consume a result
    32	 * before it is delivered, and whichever path claims first prevents duplicate
    33	 * delivery.
    34	 */
    35	export function createSubagentResultDelivery<T extends { id: string }>(
    36	  options: SubagentResultDeliveryOptions<T>,
    37	) {
    38	  const inbox = createCompletionInbox<T>();
    39	  const owner = options.owner ?? (() => ({ sessionId: "test", epoch: 0 }));
    40	
    41	  const flush = () => {
    42	    const envelopes = inbox.claim(owner());
    43	    if (envelopes.length === 0) return;
    44	    const results = envelopes.map((envelope) => envelope.payload);
    45	    try {
    46	      options.deliver(results);
    47	      inbox.acknowledge(envelopes.map((envelope) => envelope.deliveryId));
    48	    } catch (error) {
    49	      // A synchronous session teardown may reject append/send. Preserve the
    50	      // original batch ahead of anything deferred re-entrantly while delivery
    51	      // ran, so a later boundary can retry without loss or reordering.
    52	      inbox.retry(envelopes, owner());
    53	      throw error;
    54	    }
    55	  };
    56	
    57	  const queue = {
    58	    defer(result: T) {
    59	      const currentOwner = owner();
    60	      inbox.defer(
    61	        {
    62	          deliveryId: `subagent:${result.id}`,
    63	          owner: currentOwner ?? { sessionId: "unowned", epoch: 0 },
    64	          producer: "subagent",
    65	          producerId: result.id,
    66	          terminalRef: { kind: "subagent-snapshot", id: result.id },
    67	          wake: "follow-up",
    68	          payload: result,
    69	        },
    70	        currentOwner,
    71	      );
    72	      if (options.isIdle()) flush();
    73	    },
    74	    consume(ids: Iterable<string>) {
    75	      inbox.consume("subagent", ids);
    76	    },
    77	    /** Flush at the authoritative parent boundary. */
    78	    parentSettled() {
    79	      flush();
    80	    },
    81	    clear() {
    82	      inbox.clear();
    83	    },
    84	    size() {
    85	      return inbox.size();
    86	    },
    87	    inspectDeadLetters: inbox.inspectDeadLetters,
    88	  };
    89	  return queue satisfies ConsumableResultDeliveryQueue<T>;
    90	}
